// ring buffer for sustained FIFO
type ring struct { buf []int; head, count int }
func newRing(cap int) *ring {
    if cap < 1 { cap = 1 }
    return &ring{buf: make([]int, cap)}
}
func (r *ring) enqueue(v int) {
    if r.count == len(r.buf) {
        grown := make([]int, 2*len(r.buf))
        for i := 0; i < r.count; i++ {
            grown[i] = r.buf[(r.head+i)%len(r.buf)]
        }
        r.buf, r.head = grown, 0
    }
    r.buf[(r.head+r.count)%len(r.buf)] = v
    r.count++
}
func (r *ring) dequeue() (int, bool) {
    if r.count == 0 { return 0, false }
    v := r.buf[r.head]
    var zero int
    r.buf[r.head] = zero // clear slot so GC can reclaim pointed-to values
    r.head = (r.head + 1) % len(r.buf)
    r.count--
    return v, true
}

