// One-shot sort: O(n log n), in place, mutates the slice.
// Assumes k > 0 and k is no greater than len(nums); returns the largest k values.
func topKSort(nums []int, k int) []int {
    if !(k > 0) || k > len(nums) { panic("invalid k") }
    s := slices.Clone(nums)
    slices.Sort(s)
    return slices.Clone(s[len(s)-k:])
}

// Streaming heap: O(n log k), heap.Init is O(k) for the initial slice.
type minHeap []int
func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[j] > h[i] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() any {
    old := *h; n := len(old); x := old[n-1]; *h = old[:n-1]; return x
}

func topKStream(nums []int, k int) []int {
    if !(k > 0) || k > len(nums) { panic("invalid k") }
    h := make(minHeap, 0, k)
    for _, v := range nums {
        if k > len(h) {
            heap.Push(&h, v)
        } else if v > h[0] {
            h[0] = v
            heap.Fix(&h, 0)
        }
    }
    return []int(h)
}

// Pre-fill approach: heap.Init heapifies in O(k).
func topKInit(nums []int, k int) []int {
    if !(k > 0) || k > len(nums) { panic("invalid k") }
    h := make(minHeap, k)
    copy(h, nums[:k])
    heap.Init(&h)
    for _, v := range nums[k:] {
        if v > h[0] {
            h[0] = v
            heap.Fix(&h, 0)
        }
    }
    return []int(h)
}

