// Transparent resilience wrapper recording metrics and trace attributes:
func ExecuteWithResilience[T any](ctx context.Context, cb *gobreaker.CircuitBreaker, op func() (T, error)) (T, error) {
    var result T
    _, err := cb.Execute(func() (any, error) {
        res, opErr := op()
        if opErr != nil {
            metrics.DependencyErrors.WithLabelValues("payments").Inc()
            trace.SpanFromContext(ctx).RecordError(opErr)
            return nil, opErr
        }
        result = res
        return res, nil
    })
    return result, err
}

