// Canonical safe database/sql query and row iteration pattern:
func ListUsers(ctx context.Context, db *sql.DB) ([]User, error) {
    rows, err := db.QueryContext(ctx, "SELECT id, name FROM users")
    if err != nil { return nil, err }
    defer rows.Close() // Mandatory: prevents connection leak on early return

    var users []User
    for rows.Next() {
        var u User
        if err := rows.Scan(&u.ID, &u.Name); err != nil { return nil, err }
        users = append(users, u)
    }
    if err := rows.Err(); err != nil { return nil, err } // Check iteration error
    return users, nil
}

