// Periodic flush and clear pattern for batch processing in JPA:
@Transactional
public void importUsers(List<UserDTO> users) {
    int batchSize = 50;
    for (int i = 0; i < users.size(); i++) {
        User user = new User(users.get(i));
        entityManager.persist(user);
        if (i % batchSize == 0 && i > 0) {
