// Leak-free Circular Ring Buffer Queue in Go:
type Queue[T any] {
    buf        []T
    head, size int
}
func (q *Queue[T]) Enqueue(v T) {
    if q.size == len(q.buf) { q.grow() }
    idx := (q.head + q.size) % len(q.buf)
    q.buf[idx] = v
    q.size++
}
func (q *Queue[T]) Dequeue() (T, bool) {
    if q.size == 0 { var zero T; return zero, false }
    v := q.buf[q.head]
    var zero T
    q.buf[q.head] = zero // Clear slot to prevent GC memory retention!
    q.head = (q.head + 1) % len(q.buf)
    q.size--
    return v, true
}

// Idiomatic map counting with deterministic sorted iteration:
func CountAndSortWords(words []string) []struct{ Word string; Count int } {
    counts := make(map[string]int, len(words))
    for _, w := range words { counts[w]++ } // Zero-value allows direct increment

    // Deterministic sorted output:
    keys := make([]string, 0, len(counts))
    for k := range counts { keys = append(keys, k) }
    slices.Sort(keys)

    result := make([]struct{ Word string; Count int }, len(keys))
    for i, k := range keys { result[i] = struct{ Word string; Count int }{k, counts[k]} }
    return result
}

// Fast I/O template for Go coding interviews:
func FastIO() {
    in := bufio.NewReader(os.Stdin)
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush() // Mandatory flush

    var n int
    fmt.Fscan(in, &n)
    results := make([]int, 0, n) // Pre-allocate capacity
    for i := 0; i < n; i++ {
        var val int
        fmt.Fscan(in, &val)
        results = append(results, val * 2)
    }
    for _, r := range results {
        fmt.Fprintln(out, r)
    }
}
